package com.zerotrust.internalresource.entity; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="file_resources") public class FileResourceEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String resourceId; private String name; private String description; private String category; private String owner; private String department; private String classificationLevel; private String status; private Instant createdAt; private Instant updatedAt; protected FileResourceEntity(){} public Long getId(){return id;} public String getResourceId(){return resourceId;} public void setResourceId(String v){resourceId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getOwner(){return owner;} public void setOwner(String v){owner=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getClassificationLevel(){return classificationLevel;} public void setClassificationLevel(String v){classificationLevel=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} }